const allItems = $input.all().map(i => i.json);

const mainJson = allItems.find(i => i.meta !== undefined);
const image    = allItems.find(i => i.summary !== undefined);

if (image) {
  mainJson.image_processing.summary    = image.summary    ?? null;
  mainJson.image_processing.confidence_rain = image.confidence_rain ?? null;
  mainJson.image_processing.confidence_wind = image.confidence_wind ?? null;
  mainJson.image_processing.features   = image.features   ?? mainJson.image_processing.features;
}

return [{ json: mainJson }];

const main = items[0].json;

// ─── Actuators ───────────────────────────────────────────────────────────────
const filteredActuators = (main.actuators ?? [])
  .filter(a => (a.classification === 'TURN-ON' || a.classification === 'KEEP-ON'))
  .map(a => ({
    type: a.type,
    classification: a.classification,
    control_mode: a.control_mode,
    run: {
      execute_at:    a.run?.execute_at    ?? null,
      execute_until: a.run?.execute_until ?? null
    },
    re_evaluation: {
      start: a.re_evaluation?.interval?.start ?? null,
      end:   a.re_evaluation?.interval?.end   ?? null
    }
  }));


// ─── History ─────────────────────────────────────────────────────────────────
let filteredHistory = null;

if (main.history && Array.isArray(main.history.runs)) {
  // Grab up to the 10 most recent runs (assuming newest is at index 0)
  const runsToProcess = main.history.runs.slice(0, 10);
  const count = runsToProcess.length;

  if (count > 0) {
    let sumTemp = 0, sumHum = 0, sumSoil = 0, sumLight = 0;

    // Sum up the sensor values across the stored runs
    runsToProcess.forEach(r => {
      sumTemp += (r.sensors?.temp || 0);
      sumHum  += (r.sensors?.hum || 0);
      sumSoil += (r.sensors?.soil || 0);
      sumLight += (r.sensors?.light || 0);
    });

    // Output the formatted structure with integer averages
    filteredHistory = {
      avg_temp: Math.round(sumTemp / count),
      avg_hum: Math.round(sumHum / count),
      avg_soil: Math.round(sumSoil / count),
      avg_light: Math.round(sumLight / count),
      runs: main.history.runs.slice(0, 3) // Only keep the 3 latest runs
    };
  } else {
    // Fallback if the runs array is empty but exists
    filteredHistory = {
      avg_temp: null, avg_hum: null, avg_soil: null, avg_light: null, runs: []
    };
  }
}

// ─── Weather Hourly Filtering ────────────────────────────────────────────────
const triggerTime = new Date(main.meta?.triggered_at || Date.now());
const hourlyData = main.weather?.insights?.hourly || [];

let targetIndex = hourlyData.findIndex(h => new Date(h.time) >= triggerTime);
let recent_and_upcoming_forecast = [];

if (targetIndex !== -1) {
  const startIndex = Math.max(0, targetIndex - 1);
  recent_and_upcoming_forecast = hourlyData.slice(startIndex, startIndex + 5);
} else {
  recent_and_upcoming_forecast = hourlyData.slice(-5);
}

// ─── Assemble output ─────────────────────────────────────────────────────────
const output = {
  time: main.meta?.triggered_at ?? null,
  crop: main.crop ?? null,
  sensors: $input.first().json.sensors,
  weather: {
    precipitation_probability: main.weather?.precipitation_probability ?? null,
    state:                     main.weather?.state ?? null,
    summary:                   main.weather?.summary ?? null,
    insights: {
      highlights:                   main.weather?.insights?.highlights ?? null,
      recent_and_upcoming_forecast: recent_and_upcoming_forecast
    }
  },
  image_processing: main.image_processing ?? null,
  history:          filteredHistory, 
  actuators:        filteredActuators
};

return [{ json: output }];

// Retrieve the array of items coming from the previous node
const runsData = items.map(item => item.json);

