for (const run of runsData) {
  sumTemp += run.temp;
  sumHum += run.hum;
  sumSoil += run.soil;
  sumLight += run.light;
}

// Calculate the final averages (using Math.round to keep them as integers)
const count = runsData.length || 1;

// Grab ONLY the first run (the most recent one) to format for the AI
const recentRun = runsData[0];
const formattedRuns = [];

// Ensure a run actually exists before trying to format it
if (recentRun) {
  formattedRuns.push({
    date_time: recentRun.date_time,
    crop: recentRun.crop,
    mode: recentRun.mode,
    growth_stage: recentRun.growth_stage,
    sensors: {
