      confidence_rain: recentRun.confidence_rain,
      confidence_wind: recentRun.confidence_wind
    },
    weather_summary: recentRun.weather_summary,
    decision_logic: recentRun.decision_logic
  });
}

const outputPayload = {
  avg_temp: Math.round(sumTemp / count),
  avg_hum: Math.round(sumHum / count),
  avg_soil: Math.round(sumSoil / count),
  avg_light: Math.round(sumLight / count),
  // This will now be an array containing exactly 1 run
  runs: formattedRuns
};

// Return the newly structured payload
return [{ json: outputPayload }];

// 1. Fetch the main payload specifically from its node
const mainItems = $('filter only what is needed for final decisions').all();
let mainPayload = mainItems[0].json;

// 2. Fetch the pre-calculated history specifically from the get_history node
