// Check if the history node actually returned items
if (historyItems && historyItems.length > 0) {
  historyData = historyItems[0].json;

  // Just in case the JSON payload itself is wrapped in an array
  if (Array.isArray(historyData)) {
    historyData = historyData.length > 0 ? historyData[0] : null;
  }
}

// 4. Inject the history into the main payload
// If your main payload is wrapped in an array, we inject it into the first object:
