// ─── Helper Functions ────────────────────────────────────────────────────────
// Calculate interval.end while preserving the AI's timezone offset strictly
function calculateIntervalEnd(isoString, minutesToAdd) {
    if (!isoString || typeof minutesToAdd !== 'number') return null;
    const d = new Date(isoString);
    if (isNaN(d.getTime())) return null; 

    // Add the duration
    d.setMinutes(d.getMinutes() + minutesToAdd);

    // Extract original timezone offset (e.g., "+01:00" or "Z") from the AI string
    const tzMatch = isoString.match(/([+-]\d{2}:\d{2}|Z)$/);
    const tz = tzMatch ? tzMatch[1] : 'Z'; 

    // Convert the offset into total minutes
    let offsetTotal = 0;
    if (tz !== 'Z') {
        const sign = tz.startsWith('+') ? 1 : -1;
        const hours = parseInt(tz.substring(1, 3), 10);
        const mins = parseInt(tz.substring(4, 6), 10);
        offsetTotal = sign * ((hours * 60) + mins);
    }

    // Shift the date temporarily so standard UTC methods output your local time correctly
    const local = new Date(d.getTime() + (offsetTotal * 60000));

    // Reconstruct the string manually with the original offset (NO milliseconds)
    const pad = (n) => String(n).padStart(2, '0');
    return `${local.getUTCFullYear()}-${pad(local.getUTCMonth() + 1)}-${pad(local.getUTCDate())}T${pad(local.getUTCHours())}:${pad(local.getUTCMinutes())}:${pad(local.getUTCSeconds())}${tz}`;
}

// ─── Main Execution ──────────────────────────────────────────────────────────

// 1. Get the main environmental data from the "Merge the results" node.
let mainData = JSON.parse(JSON.stringify($('Merge the results').first().json));

// 2. Safely extract and parse the AI's stringified output
let rawOutput = $input.first().json.output || "[]";

// Clean up markdown just in case the AI hallucinates backticks
rawOutput = rawOutput.replace(/```json/g, '').replace(/```/g, '').trim();

let decisions = [];
try {
  decisions = JSON.parse(rawOutput);
} catch (e) {
  console.error("Failed to parse AI output:", e.message);
}

// 3. Map the parsed AI decisions to the main actuators array
let actuators = mainData.actuators || [];

for (let actuator of actuators) {
  // Find the AI decision for this specific actuator
  let decision = decisions.find(d => d.actuator === actuator.type);

  if (decision) {
    if (decision.action === "NEED-RE-EVALUATION") {
      // Map the action to classification to act as the "snooze" state
      actuator.classification = "NEED-RE-EVALUATION";
      actuator.re_evaluation.active = true;

      // Inject reasoning into recommended_action
      actuator.recommended_action = decision.reasoning;

      // Calculate the Date-Time Interval using the timezone-preserving function
      if (decision.re_evaluation_start && decision.re_evaluation_duration_minutes) {
        actuator.re_evaluation.interval.start = decision.re_evaluation_start;
        actuator.re_evaluation.interval.end = calculateIntervalEnd(
            decision.re_evaluation_start, 
            decision.re_evaluation_duration_minutes
        );
      } else {
        // Fallback just in case the AI missed the dates
        actuator.re_evaluation.interval.start = null;
        actuator.re_evaluation.interval.end = null;
      }

    } else if (decision.action === "PROCEED") {
      // If proceeding, we leave the base classification intact
      actuator.re_evaluation.active = false;
      actuator.re_evaluation.interval.start = null;
      actuator.re_evaluation.interval.end = null;

      // Ensure recommended_action is cleared since it's not needed for PROCEED here
      actuator.recommended_action = null; 
    }
  }
}

// 4. Return the fully merged and updated environmental data
return [{ json: mainData }];

