const originalState = $('continue_execution').first().json;
let updatedState = JSON.parse(JSON.stringify(originalState));

// 2. Fetch the text output from the Final Correction Agent
const agentText = $input.first().json.output || ""; 

// 3. Parse the Agent's text blocks into a structured dictionary
const parsedDecisions = {};
const blocks = agentText.split(/\n*---\n*/);

blocks.forEach(block => {
    if (!block.trim() || block.includes("no actuators")) return;

    let actuatorType = "";
    let action = "";
    let reasoning = "";
    let executeAt = null;
    let duration = null;

    // Read line by line to extract variables
    const lines = block.split('\n');
    lines.forEach(line => {
        if (line.startsWith('ACTUATOR:')) actuatorType = line.replace('ACTUATOR:', '').trim();
        else if (line.startsWith('ACTION:')) action = line.replace('ACTION:', '').trim();
        else if (line.startsWith('REASONING:')) reasoning = line.replace('REASONING:', '').trim();
        else if (line.startsWith('EXECUTE_AT:')) executeAt = line.replace('EXECUTE_AT:', '').trim();
        else if (line.startsWith('DURATION_MINUTES:')) duration = parseInt(line.replace('DURATION_MINUTES:', '').trim(), 10);
    });

    if (actuatorType) {
        parsedDecisions[actuatorType] = { action, reasoning, executeAt, duration };
    }
});

